"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[3770],{3800:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"recruitment-2026","metadata":{"permalink":"/vi/blog/recruitment-2026","editUrl":"https://github.com/ACLAB-HCMUT/ACLAB-HCMUT.github.io/tree/main/blog/2026-06-15-recruitment-2026.md","source":"@site/blog/2026-06-15-recruitment-2026.md","title":"ACLAB is recruiting student members for 2026","description":"ACLAB is opening applications for new undergraduate and graduate members for 2026.","date":"2026-06-15T00:00:00.000Z","tags":[{"inline":false,"label":"Recruitment","permalink":"/vi/blog/tags/recruitment","description":"Recruitment and openings"},{"inline":false,"label":"News","permalink":"/vi/blog/tags/news","description":"Lab news and announcements"}],"readingTime":0.505,"hasTruncateMarker":true,"authors":[{"name":"ACLAB","title":"Advanced Computing Lab, HCMUT","url":"https://github.com/ACLAB-HCMUT","page":{"permalink":"/vi/blog/authors/aclab"},"socials":{"github":"https://github.com/ACLAB-HCMUT"},"imageURL":"https://github.com/ACLAB-HCMUT.png","key":"aclab"}],"frontMatter":{"slug":"recruitment-2026","title":"ACLAB is recruiting student members for 2026","authors":["aclab"],"tags":["recruitment","news"]},"unlisted":false,"nextItem":{"title":"Seminar: Edge AI for real-time visual inspection","permalink":"/vi/blog/seminar-edge-ai-inspection"}},"content":"ACLAB is opening applications for new **undergraduate and graduate members** for 2026.\\nWe are looking for students excited to build real intelligent systems \u2014 robots, AGVs,\\ncustom PCBs, embedded devices and edge-AI applications.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Who we are looking for\\n\\n- Undergraduate research members (robotics, embedded, edge AI)\\n- Graduate researchers (MSc/PhD)\\n- Student hardware / PCB engineers\\n\\nNo prior research experience is required for undergraduate roles \u2014 curiosity and\\nwillingness to learn hardware and firmware matter most.\\n\\n## How to apply\\n\\nSee the [Join ACLAB](/join) page for positions, requirements and the application\\nprocess, or email us at **aclab@hcmut.edu.vn**."},{"id":"seminar-edge-ai-inspection","metadata":{"permalink":"/vi/blog/seminar-edge-ai-inspection","editUrl":"https://github.com/ACLAB-HCMUT/ACLAB-HCMUT.github.io/tree/main/blog/2026-05-20-seminar-edge-ai.md","source":"@site/blog/2026-05-20-seminar-edge-ai.md","title":"Seminar: Edge AI for real-time visual inspection","description":"This month\'s lab seminar covers deploying quantized vision models on embedded","date":"2026-05-20T00:00:00.000Z","tags":[{"inline":false,"label":"Seminar","permalink":"/vi/blog/tags/seminar","description":"Talks and seminars"},{"inline":false,"label":"News","permalink":"/vi/blog/tags/news","description":"Lab news and announcements"}],"readingTime":0.39,"hasTruncateMarker":true,"authors":[{"name":"ACLAB","title":"Advanced Computing Lab, HCMUT","url":"https://github.com/ACLAB-HCMUT","page":{"permalink":"/vi/blog/authors/aclab"},"socials":{"github":"https://github.com/ACLAB-HCMUT"},"imageURL":"https://github.com/ACLAB-HCMUT.png","key":"aclab"}],"frontMatter":{"slug":"seminar-edge-ai-inspection","title":"Seminar: Edge AI for real-time visual inspection","authors":["aclab"],"tags":["seminar","news"]},"unlisted":false,"prevItem":{"title":"ACLAB is recruiting student members for 2026","permalink":"/vi/blog/recruitment-2026"},"nextItem":{"title":"ACLAB team reaches national robotics competition finals","permalink":"/vi/blog/robotics-competition-finals"}},"content":"This month\'s lab seminar covers **deploying quantized vision models on embedded\\naccelerators** for real-time quality control on the factory floor.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Topics\\n\\n- Model quantization and pruning for edge devices\\n- Running inference on Jetson with TensorRT\\n- Measuring latency, throughput and power on-device\\n- A walkthrough of our visual-inspection project pipeline\\n\\nThe session is open to all lab members and interested students. Slides and demo\\ncode will be shared in the [Knowledge Base](/docs/intro) afterwards."},{"id":"robotics-competition-finals","metadata":{"permalink":"/vi/blog/robotics-competition-finals","editUrl":"https://github.com/ACLAB-HCMUT/ACLAB-HCMUT.github.io/tree/main/blog/2026-04-10-robotics-competition.md","source":"@site/blog/2026-04-10-robotics-competition.md","title":"ACLAB team reaches national robotics competition finals","description":"Our autonomous AGV team reached the finals of a national robotics competition","date":"2026-04-10T00:00:00.000Z","tags":[{"inline":false,"label":"Competition","permalink":"/vi/blog/tags/competition","description":"Competitions and contests"},{"inline":false,"label":"News","permalink":"/vi/blog/tags/news","description":"Lab news and announcements"}],"readingTime":0.355,"hasTruncateMarker":true,"authors":[{"name":"ACLAB","title":"Advanced Computing Lab, HCMUT","url":"https://github.com/ACLAB-HCMUT","page":{"permalink":"/vi/blog/authors/aclab"},"socials":{"github":"https://github.com/ACLAB-HCMUT"},"imageURL":"https://github.com/ACLAB-HCMUT.png","key":"aclab"}],"frontMatter":{"slug":"robotics-competition-finals","title":"ACLAB team reaches national robotics competition finals","authors":["aclab"],"tags":["competition","news"]},"unlisted":false,"prevItem":{"title":"Seminar: Edge AI for real-time visual inspection","permalink":"/vi/blog/seminar-edge-ai-inspection"}},"content":"Our autonomous AGV team reached the **finals of a national robotics competition**\\nwith a LiDAR-based navigation stack designed and built entirely in the lab.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Highlights\\n\\n- Differential-drive AGV with custom motor-driver PCBs\\n- LiDAR SLAM and ROS 2 navigation\\n- Real-time obstacle avoidance and path planning\\n\\nCongratulations to the team! The platform continues as one of our active\\n[projects](/projects). Want to build the next one? [Join ACLAB](/join)."}]}}')}}])